        if (k === 'paint') {
          ctx.fillStyle = '#16288a'; ctx.fillRect(X, Y, 16, 16); ctx.fillStyle = '#2a5ad8'; ctx.fillRect(X, Y + 2, 16, 12); ctx.fillStyle = '#9ab8ff'; ctx.fillRect(X, Y, 16, 3); ctx.fillStyle = '#ffffff'; ctx.fillRect(X + 2 + (h & 7), Y + 1, 5, 1);
          if (ty === 21 && h % 3 === 0) { ctx.fillStyle = '#2a5ad8'; ctx.fillRect(X + 3 + (h & 7), Y + 16, 3, 5 + (h & 3)); } return true;
        }
