            ctx.strokeStyle = `rgba(${rgbOf(q.c)},0.85)`; ctx.lineWidth = 1; ctx.setLineDash && ctx.setLineDash([3, 3]); ctx.strokeRect(X - w / 2 + 0.5, top + 0.5, w - 1, Y - top - 1); ctx.setLineDash && ctx.setLineDash([]);
            ctx.beginPath(); for (let yy = top + 4; yy < Y - 4; yy += 6) { ctx.moveTo(X - w / 2 + 3, yy + 3); ctx.lineTo(X + w / 2 - 3, yy - 2); } ctx.stroke();
