          ctx.fillStyle = '#e8dcc0'; ctx.fillRect(-3, 3, 6, 5); ctx.fillStyle = c[0]; ctx.fillRect(-3, 5, 6, 1); ctx.fillStyle = c[2]; ctx.beginPath(); ctx.moveTo(-3, -8); ctx.lineTo(0, -12); ctx.lineTo(3, -8); ctx.fill();
