          DD.text('BLUE', 16, 19, '#16288a', 1, null, 'center'); ctx.fillStyle = '#2a2420'; ctx.fillRect(14, 2, 4, 4); ctx.strokeStyle = '#6a6a74'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(16, 6, 12, Math.PI, 0); ctx.stroke();
